/// Returns a new `Vec<u8>` containing `count` bytes copied contiguously
/// from `buffer`, starting at index `offset`.
///
/// Preconditions (as stated in the problem):
/// - `offset + count <= buffer.len()`
/// - `count == 0` OR `offset < buffer.len()`
fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Slice the requested window and copy it into a new Vec<u8>.
    buffer[offset..offset + count].to_vec()
}

